fn push_rules_rule_5401(rules: &mut Vec<RubiRule>) {
    rubi_symb!(symbols; a__, b__, c__, d_, e__, f__, m_, p_, x_);
    rules.push(rubi_rule!(
        order: 5401,
        source: "Int[(f_.*x_)^m_.*(a_.+b_.*ArcTan[c_.*x_])^p_./(d_+e_.*x_),x_Symbol] :=
          f/e \\[Star] Int[(f*x)^(m-1)*(a+b*ArcTan[c*x])^p,x] -
          d*f/e \\[Star] Int[(f*x)^(m-1)*(a+b*ArcTan[c*x])^p/(d+e*x),x] /;
        FreeQ[{a,b,c,d,e,f},x] && IGtQ[p,0] && EqQ[c^2*d^2+e^2,0] && GtQ[m,0]",
        desc: "Algebraic expansion",
        refs: [],
        pattern:  rubi_shared_pattern_15(symbols),
        with: [f__, m_, a__, b__, c__, p_, d_, e__, x_],
        optional: [f__, m_, a__, b__, c__, p_, e__],
        when: {
            freeq!([a__, b__, c__, d_, e__, f__], x_)
                && igtq!(p_, 0)
                && eqq!(c__.pow(2) * d_.pow(2) + e__.pow(2), 0)
                && gtq!(m_, 0)
        },
        rhs: {
            let scaled_x = &f__ * x_;
            let argument = &a__ + &b__ * (&c__ * x_).atan();
            let recursive_base = scaled_x.pow(&m_ - 1) * argument.pow(&p_);
            rubi_star(&f__ / &e__, rubi_rhs_int(&recursive_base, x_))
                    - rubi_star(&d_ * &f__ / &e__, rubi_rhs_int(&(recursive_base / (&d_ + &e__ * x_)), x_))
        },
    ));
}

