fn push_rules_rule_5403(rules: &mut Vec<RubiRule>) {
    rubi_symb!(a__, b__, c__, d_, e__, p_, x_);
    rules.push(rubi_rule!(
        order: 5403,
        source: "Int[(a_.+b_.*ArcTan[c_.*x_])^p_./(x_*(d_+e_.*x_)),x_Symbol] :=
          (a+b*ArcTan[c*x])^p*Log[2-2/(1+e*x/d)]/d -
          b*c*p/d \\[Star] Int[(a+b*ArcTan[c*x])^(p-1)*Log[2-2/(1+e*x/d)]/(1+c^2*x^2),x] /;
        FreeQ[{a,b,c,d,e},x] && IGtQ[p,0] && EqQ[c^2*d^2+e^2,0]",
        desc: "Integration by parts",
        refs: [],
        pattern: (a__ + b__ * (c__ * x_).atan()).pow(p_) / (x_ * (d_ + e__ * x_)),
        with: [a__, b__, c__, p_, d_, e__, x_],
        optional: [a__, b__, c__, p_, e__],
        when: {
            freeq!([a__, b__, c__, d_, e__], x_)
                && igtq!(p_, 0)
                && eqq!(c__.pow(2) * d_.pow(2) + e__.pow(2), 0)
        },
        rhs: {
            let argument = &a__ + &b__ * (&c__ * x_).atan();
            let logarithm = (Atom::num(2) - Atom::num(2) / (Atom::num(1) + &e__ * x_ / &d_)).log();
            let recursive = argument.pow(&p_ - 1) * &logarithm
                / (Atom::num(1) + c__.pow(2) * x_.pow(2));
            rubi_simp(&(argument.pow(&p_) * logarithm / &d_), x_)
                    - rubi_star(&b__ * &c__ * &p_ / &d_, rubi_rhs_int(&recursive, x_))
        },
    ));
}

