fn push_rules_rule_5405(rules: &mut Vec<RubiRule>) {
    rubi_symb!(symbols; a__, b__, c__, d_, e__, f__, m_, p_, x_);
    rules.push(rubi_rule!(
        order: 5405,
        source: "Int[(f_.*x_)^m_*(a_.+b_.*ArcTan[c_.*x_])^p_./(d_+e_.*x_),x_Symbol] :=
          1/d \\[Star] Int[(f*x)^m*(a+b*ArcTan[c*x])^p,x] -
          e/(d*f) \\[Star] Int[(f*x)^(m+1)*(a+b*ArcTan[c*x])^p/(d+e*x),x] /;
        FreeQ[{a,b,c,d,e,f},x] && IGtQ[p,0] && EqQ[c^2*d^2+e^2,0] && LtQ[m,-1]",
        desc: "Algebraic expansion",
        refs: [],
        pattern:  rubi_shared_pattern_15(symbols),
        with: [f__, m_, a__, b__, c__, p_, d_, e__, x_],
        optional: [f__, a__, b__, c__, p_, e__],
        when: {
            freeq!([a__, b__, c__, d_, e__, f__], x_)
                && igtq!(p_, 0)
                && eqq!(c__.pow(2) * d_.pow(2) + e__.pow(2), 0)
                && ltq!(m_, -1)
        },
        rhs: {
            let scaled_x = &f__ * x_;
            let argument = &a__ + &b__ * (&c__ * x_).atan();
            let base = scaled_x.pow(&m_) * argument.pow(&p_);
            let recursive = scaled_x.pow(&m_ + 1) * (&a__ + &b__ * (&c__ * x_).atan()).pow(&p_)
                / (&d_ + &e__ * x_);
            rubi_star(Atom::num(1) / &d_, rubi_rhs_int(&base, x_))
                    - rubi_star(&e__ / (&d_ * &f__), rubi_rhs_int(&recursive, x_))
        },
    ));
}

