fn push_rules_rule_5407(rules: &mut Vec<RubiRule>) {
    rubi_symb!(a__, b__, c__, d__, e__, f__, m_, q_, x_);
    rules.push(rubi_rule!(
        order: 5407,
        source: "Int[(f_.*x_)^m_.*(d_.+e_.*x_)^q_.*(a_.+b_.*ArcTan[c_.*x_]),x_Symbol] :=
          With[{u=IntHide[(f*x)^m*(d+e*x)^q,x]},
          (a+b*ArcTan[c*x]) \\[Star] u - b*c \\[Star] Int[SimplifyIntegrand[u/(1+c^2*x^2),x],x]] /;
        FreeQ[{a,b,c,d,e,f,q},x] && NeQ[q,-1] && IntegerQ[2*m] && (IGtQ[m,0] && IGtQ[q,0] || ILtQ[m+q+1,0] && LtQ[m*q,0])",
        desc: "Integration by parts",
        refs: [],
        pattern: (f__ * x_).pow(m_) * (d__ + e__ * x_).pow(q_) * (a__ + b__ * (c__ * x_).atan()),
        with: [f__, m_, d__, e__, q_, a__, b__, c__, x_],
        optional: [f__, m_, d__, e__, q_, a__, b__, c__],
        when: {
            freeq!([a__, b__, c__, d__, e__, f__, q_], x_)
                && neq!(q_, -1)
                && integerq!(Atom::num(2) * &m_)
                && ((igtq!(m_, 0) && igtq!(q_, 0)) || (iltq!(&m_ + &q_ + 1, 0) && ltq!(&m_ * &q_, 0)))
        },
        rhs: {
            let hidden = rubi_int_hide(&((&f__ * x_).pow(&m_) * (&d__ + &e__ * x_).pow(&q_)), x_).rubi_rhs();
            let argument = &a__ + &b__ * (&c__ * x_).atan();
            let recursive = rubi_simplify_integrand(&(&hidden / (Atom::num(1) + c__.pow(2) * x_.pow(2))), x_);
            rubi_star(argument, hidden)
                    - rubi_star(&b__ * &c__, rubi_rhs_int(&recursive, x_))
        },
    ));
}

